const SECRET_KEY = $env.ATHENE_SECRET_KEY;
if (!SECRET_KEY) throw new Error('ATHENE_SECRET_KEY nao definida nas variaveis de ambiente do n8n.');
const timestamp = Date.now().toString();
const port = $('Hub Proxy 4').item.json.proxy.porta || 0;
const dataObj = { porta: port };
const dataStr = JSON.stringify(dataObj);
const crypto = require('crypto');
const signature = crypto.createHmac('sha256', SECRET_KEY).update(timestamp + dataStr).digest('hex');
return { json: { req_body: { data: dataStr, timestamp: parseInt(timestamp), signature } } };

