let port = 0;
let executed_p1 = false, executed_p5 = false, executed_p3 = false, executed_p4 = false, executed_desativar = false;

// Pergunta isoladamente
try { executed_p1 = !!$('Set Proxy ').first(0, $runIndex); } catch(e) {}
try { executed_p5 = !!$('Set Proxy 5').first(0, $runIndex); } catch(e) {}
try { executed_p3 = !!$('Set Proxy (3)').first(0, $runIndex); } catch(e) {}
try { executed_p4 = !!$('Set Proxy (4)').first(0, $runIndex); } catch(e) {}
try { executed_desativar = !!$('Desativar Proxy1').first(0, $runIndex); } catch(e) {}

if (executed_p1) {
    try { port = $('Hub ').first(0, $runIndex).json.proxy.porta; } catch(e) {}
} else if (executed_p5) {
    try { port = $('Hub 5').first(0, $runIndex).json.proxy.porta; } catch(e) {}
} else if (executed_p3) {
    try { port = $('Hub Proxy 3').first(0, $runIndex).json.proxy.porta; } catch(e) {}
} else if (executed_p4) {
    try { port = $('Hub Proxy 4').first(0, $runIndex).json.proxy.porta; } catch(e) {}
} else if (executed_desativar) {
    port = 0;
}

const SECRET_KEY = $env.ATHENE_SECRET_KEY;
if (!SECRET_KEY) throw new Error('ATHENE_SECRET_KEY nao definida nas variaveis de ambiente do n8n.');
const timestamp = Date.now().toString();
const dataObj = { porta: port, instance: $('Set BaseURL1').item.json.instance };
const dataStr = JSON.stringify(dataObj);
const crypto = require('crypto');
const signature = crypto.createHmac('sha256', SECRET_KEY).update(timestamp + dataStr).digest('hex');

return { json: { req_body: { data: dataStr, timestamp: parseInt(timestamp), signature } } };

